&lt;ul&gt;
&lt;li style=&quot;font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;Hybrid working&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
